import{_ as a,c as r,o as t,a3 as o}from"./chunks/framework.BurWKwwG.js";const g=JSON.parse('{"title":"Introduction & Overview","description":"","frontmatter":{},"headers":[],"relativePath":"1_overview.md","filePath":"1_overview.md"}'),i={name:"1_overview.md"};function n(s,e,l,c,d,h){return t(),r("div",null,e[0]||(e[0]=[o('<h1 id="introduction-overview" tabindex="-1">Introduction &amp; Overview <a class="header-anchor" href="#introduction-overview" aria-label="Permalink to “Introduction &amp; Overview”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>CBD3 (Colorectal Cancer Biomarker Database, 3rd Edition) is a comprehensive platform that integrates biomarker literature data, clinical data, and single-cell RNA sequencing (scRNA-seq) data to accelerate colorectal cancer research.</p><h3 id="what-cbd3-offers" tabindex="-1">What CBD3 Offers <a class="header-anchor" href="#what-cbd3-offers" aria-label="Permalink to “What CBD3 Offers”">​</a></h3><ul><li><strong>Biomarker Database</strong>: Curated colorectal cancer biomarkers mined from PubMed literature and manually validated by domain experts</li><li><strong>Gene Expression Atlas</strong>: Interactive UMAP-based single-cell gene expression visualization</li><li><strong>Protein Interaction Networks</strong>: PPI networks sourced from the STRING database, with expansion, module detection, proximity testing, enrichment analysis and reproducible exports</li><li><strong>MAMOF Framework</strong>: Multi-Ancestry Multi-Omics Framework for identifying universal and population-specific biomarkers</li><li><strong>Advanced Search</strong>: Multi-condition search across the biomarker database with save/load support</li></ul><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start”">​</a></h2><ol><li><strong>Browse Biomarkers</strong>: Visit the <a href="/biomarkers">Biomarkers</a> page to explore curated biomarker records</li><li><strong>Search</strong>: Use the homepage search bar or the <a href="/advanced">Advanced Search</a> page for complex queries</li><li><strong>Explore Expression</strong>: Open the <a href="/umap">UMAP Explorer</a> to visualize scRNA-seq UMAP plots</li><li><strong>Analyze Networks</strong>: Open <a href="/network">Network Analysis</a> to build, expand and statistically analyze PPI networks</li><li><strong>Learn the Framework</strong>: Read about the <a href="/mamof">MAMOF Framework</a></li><li><strong>Download</strong>: Export data from the <a href="/download">Download</a> page</li></ol><h2 id="data-sources" tabindex="-1">Data Sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to “Data Sources”">​</a></h2><p>CBD3 integrates data from the following authoritative sources:</p><ul><li><strong>PubMed</strong>: Curated biomarker records from scientific literature</li><li><strong>TCGA</strong>: Clinical validation data (COAD and READ cohorts)</li><li><strong>GEO</strong>: Single-cell RNA sequencing datasets</li><li><strong>STRING</strong>: Protein-protein interaction networks</li><li><strong>DrugBank</strong>: Drug-target association data</li><li><strong>Pathway Databases</strong>: KEGG, Reactome, GO, and others</li></ul><h2 id="technology-stack" tabindex="-1">Technology Stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to “Technology Stack”">​</a></h2><ul><li><strong>Frontend</strong>: Vue 3, Vite, Element Plus, ECharts, Cytoscape.js</li><li><strong>Backend</strong>: Node.js, Express 5, MySQL2</li><li><strong>Database</strong>: MySQL (12+ tables, ~36.4M rows)</li><li><strong>Build</strong>: Vite, pnpm</li><li><strong>Documentation</strong>: VitePress</li></ul><h2 id="citation" tabindex="-1">Citation <a class="header-anchor" href="#citation" aria-label="Permalink to “Citation”">​</a></h2><p>If you use CBD3 in your research, please cite our work. See the <a href="/docs/5_cite.html">Cite &amp; Support</a> page for details.</p><h2 id="for-developers" tabindex="-1">For Developers <a class="header-anchor" href="#for-developers" aria-label="Permalink to “For Developers”">​</a></h2><p>CBD3 is an open-source project released under the MIT license. See the <a href="/docs/4_dev.html">Developer Guide</a> for technical documentation.</p>',16)]))}const p=a(i,[["render",n]]);export{g as __pageData,p as default};
